import React from 'react';
import {BrowserRouter as Router, Routes, Route} from 'react-router-dom';
import HomePage from './components/HomePage';
import DiseaseList from './components/DiseaseList';
import DiseaseDetail from'./components/DiseaseDetail';
import CategoryList from './components/CategoryList';
import SymptomList from './components/SymptomList';
import CauseList from './components/CauseList';
import AdminPanel from './components/AdminPanel';
import Chatbot from './components/Chatbot';
import ServiceList from './components/ServiceList';
import BMICalculator from './components/BMICalculator';
import BodyFatCalculator from './components/BodyFatCalculator';
import BloodDonorPage from './components/BloodDonationPage';
import Surgeryplanner from './components/Surgeryplanner';
import GovernmentSchemes from './components/GovernmentSchemes';

function App(){
  return (
    <Router>
      <Routes>
        <Route path="/" element={<HomePage/>} />
        <Route path="/diseases" element={<DiseaseList/>} />
        <Route path="/diseases/:id" element={<DiseaseDetail/>} />
        <Route path="/categories" element={<CategoryList/>} />
        <Route path="/symptoms" element={<SymptomList/>} />
        <Route path="/causes" element={<CauseList/>} />
        <Route path="/chatbot" element={<Chatbot/>} />
        <Route path="/admin" element={<AdminPanel/>} />
        <Route path="/services" element={<ServiceList />} />
        <Route path="/services/bmi-calculator" element={<BMICalculator />} />
        <Route path="/services/fat-percentage-calculator" element={<BodyFatCalculator />} />
        <Route path="services/blood-donation" element={<BloodDonorPage/>} />
        <Route path="services/schemes" element={<GovernmentSchemes />} />
        
      </Routes>
    </Router>
  );
}

export default App;