import React from 'react';
import './ServiceList.css'; // Assuming the CSS file is named ServicesList.css

function ServiceList() {
    const services = [
        {
            path: '/services/bmi-calculator',
            icon: 'https://cdn-icons-png.flaticon.com/512/1924/1924635.png', // Icon for BMI Calculator
            title: 'BMI Calculator',
            description: 'Calculate your Body Mass Index easily.',
        },
        {
            path: '/services/fat-percentage-calculator',
            icon: 'https://cdn-icons-png.flaticon.com/128/863/863611.png', // Icon for Fat percentage Calculator
            title: 'Fat Percentage Calculator',
            description: 'Calculate your Body Fat Percentage easily.',
        },
        {
            path: '/services/blood-donation',
            icon: 'https://cdn-icons-png.flaticon.com/128/3364/3364895.png', // Icon for Blood Donation
            title: 'Blood Donation Camps',
            description: 'Find nearby blood donation camps and become a donor.',
        },
        
        {
            path: '/services/schemes',
            icon: 'https://cdn-icons-png.flaticon.com/128/12193/12193821.png', // Icon for Free Health Services
            title: 'Government Schemes',
            description: 'Discover Health services provided by Government for you.',
        },
    ];

    return (
        <div className="services-list-container">
            <h2>Our Services</h2>
            <div className="services-list">
                {services.map((service, index) => (
                    <div key={index} className="service-item">
                        <a href={service.path} style={{ textDecoration: 'none', color: 'white' }}>
                            <img src={service.icon} alt={service.title} className="service-icon" />
                            <h3>{service.title}</h3>
                            <p>{service.description}</p>
                        </a>
                    </div>
                ))}
            </div>
            
            <a href="/" className="home-button" >
                
                Home
            </a>
        </div>
    );
}

export default ServiceList;
