import React, { useState, useEffect } from "react";
import './BMICalculator.css'; // Ensure the CSS is applied correctly

const BMICalculator = () => {
  const [weight, setWeight] = useState("");
  const [height, setHeight] = useState("");
  const [age, setAge] = useState("");
  const [gender, setGender] = useState("");
  const [unitSystem, setUnitSystem] = useState("metric"); // 'metric' or 'imperial'
  const [bmi, setBmi] = useState(null);
  const [message, setMessage] = useState("");
  const [healthyWeight, setHealthyWeight] = useState("");

  // Function to calculate BMI based on input values
  const calculateBMI = () => {
    if (weight && height && age && gender) {
      let calculatedBMI = 0;
      let heightInMeters = 0;

      // Adjust units based on the selected system (metric or imperial)
      if (unitSystem === "metric") {
        heightInMeters = height / 100; // height in meters
        calculatedBMI = (weight / (heightInMeters * heightInMeters)).toFixed(2);
      } else {
        heightInMeters = height * 0.0254; // Convert inches to meters
        weight = weight * 0.453592; // Convert pounds to kilograms
        calculatedBMI = ((weight / (heightInMeters * heightInMeters)) * 703).toFixed(2); // BMI formula for imperial
      }

      setBmi(calculatedBMI);

      // Suggesting healthy weight range
      const minWeight = 18.5 * heightInMeters * heightInMeters;
      const maxWeight = 24.9 * heightInMeters * heightInMeters;

      setHealthyWeight(`Your healthy weight range should be between ${minWeight.toFixed(1)} kg and ${maxWeight.toFixed(1)} kg.`);

      // BMI category based on gender and age (no physical changes, just interpretation)
      let healthMessage = "";
      if (calculatedBMI < 18.5) {
        healthMessage = "You are underweight. Try to gain some weight.";
      } else if (calculatedBMI >= 18.5 && calculatedBMI <= 24.9) {
        healthMessage = "You are fit! Keep up the good work!";
      } else if (calculatedBMI >= 25 && calculatedBMI <= 29.9) {
        healthMessage = "You are overweight. Consider losing some weight.";
      } else {
        healthMessage = "You are obese. Please consult a doctor for advice.";
      }

      setMessage(healthMessage);
    } else {
      setMessage("Please enter all fields.");
      setBmi(null);
      setHealthyWeight("");
    }
  };

  // Recalculate BMI whenever input values change
  useEffect(() => {
    calculateBMI();
  }, [weight, height, age, gender, unitSystem]);

  // Function to display the BMI formula dynamically based on selected unit system
  const getBMICalculationFormula = () => {
    if (unitSystem === "metric") {
      return "BMI = weight (kg) / height² (m²)";
    } else {
      return "BMI = (weight (lbs) / height² (inches²)) * 703";
    }
  };

  return (
    <div className="bmi-calculator-wrapper">
      {/* Main container for left, center, and right sections */}
      <div className="bmi-main-container">
        {/* Left side BMI Ranges */}
        <div className="bmi-ranges">
          <h3>BMI Ranges</h3>
          <div className="bmi-range">
            <i className="fas fa-weight-hanging icon-underweight"></i>
            <p>Underweight</p>
            <p><small>BMI less than 18.5</small></p>
          </div>
          <div className="bmi-range">
            <i className="fas fa-heart icon-healthy"></i>
            <p>Healthy</p>
            <p><small>BMI between 18.5 - 24.9</small></p>
          </div>
          <div className="bmi-range">
            <i className="fas fa-exclamation-triangle icon-overweight"></i>
            <p>Overweight</p>
            <p><small>BMI between 25 - 29.9</small></p>
          </div>
          <div className="bmi-range">
            <i className="fas fa-syringe icon-obese"></i>
            <p>Obese</p>
            <p><small>BMI 30 or above</small></p>
          </div>
        </div>

        {/* Centered BMI Calculator */}
        <div className="bmi-calculator">
          <h2>BMI Calculator</h2>
          <div className="input-fields">
            <select
              value={unitSystem}
              onChange={(e) => setUnitSystem(e.target.value)}
              className="unit-select"
            >
              <option value="metric">Metric (kg, cm)</option>
              <option value="imperial">Imperial (lbs, inches)</option>
            </select>
            <div className="input-group">
              <input
                type="number"
                value={weight}
                onChange={(e) => setWeight(e.target.value)}
                placeholder={`Enter your weight (${unitSystem === 'metric' ? 'kg' : 'lbs'})`}
                className="input-field"
              />
            </div>
            <input
              type="number"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
              placeholder={`Enter your height (${unitSystem === 'metric' ? 'cm' : 'inches'})`}
              className="input-field"
            />
            <input
              type="number"
              value={age}
              onChange={(e) => setAge(e.target.value)}
              placeholder="Enter your age"
              className="input-field"
            />
            <select
              value={gender}
              onChange={(e) => setGender(e.target.value)}
              className="gender-select"
            >
              <option value="">Select Gender</option>
              <option value="male">Male</option>
              <option value="female">Female</option>
            </select>
          </div>

          {bmi && (
            <div className="bmi_result">
              <h3>Your BMI is: {bmi}</h3>
              <p>{message}</p>
              <p>{healthyWeight}</p>
            </div>
          )}
        </div>

        {/* Right side BMI Formulae */}
        <div className="bmi-formula">
          <h3>BMI Calculation Formulae</h3>
          <p>{getBMICalculationFormula()}</p>
        </div>
      </div>
    </div>
  );
};

export default BMICalculator;
