//DiseaseDetail.js
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import './DiseaseDetail.css'; // Import the CSS for styling
import Footer from './Footer';
function DiseaseDetail() {
    const { id } = useParams(); // Extract disease ID from the URL
    const navigate = useNavigate();
    const [disease, setDisease] = useState(null);
    const [error, setError] = useState(null);

    useEffect(() => {
        fetch(`http://127.0.0.1:8000/api/diseases/${id}/`) // Ensure this URL is correct
            .then(response => {
                if (!response.ok) {
                    throw new Error('Failed to fetch disease details');
                }
                return response.json();
            })
            .then(data => setDisease(data))
            .catch(error => {
                console.error('Error fetching disease details:', error);
                setError('Failed to load disease details. Please try again later.');
            });
    }, [id]);

    if (error) {
        return <div className="error-message">{error}</div>;
    }

    if (!disease) {
        return (
            <div className="loading-container">
                <div className="spinner"></div>
                <p>Loading disease details...</p>
            </div>
        );
    }

    return (
        <div className='disease-detail'>
        <div className="disease-detail-container">
            <header className="header">
                <button className="nav-button" onClick={() => navigate('/')}>
                    <i className="fas fa-home"></i> Home
                </button>
                <button className="nav-button" onClick={() => navigate(-1)}>
                    <i className="fas fa-arrow-left"></i> Back
                </button>
            </header>
            <h2 className="disease-title">{disease.name}</h2>
            <div className="disease-description">
                <h3>Description:</h3>
                <p>{disease.description}</p>
            </div>
            <div className="disease-info">
                <p><strong>Category:</strong> {disease.category}</p>
                <p><strong>Causes:</strong> {disease.causes}</p>
                <p><strong>Symptoms:</strong> {disease.symptoms}</p>
                <p><strong>Precautions:</strong> {disease.precautions}</p>
                <p><strong>Medicines:</strong> {disease.medicines || 'Not specified'}</p>
            </div>

            
        </div>
        <Footer />
    </div>
    );
}

export default DiseaseDetail;
