//Chatbot.js
import React, { useState, useEffect, useRef } from 'react';
import fuzzysort from 'fuzzysort';
import { translate } from '@vitalets/google-translate-api'; // Import translation function
import './Chatbot.css';
import Navbar from './Navbar';
import { useNavigate } from 'react-router-dom';

function Chatbot() {
  const [messages, setMessages] = useState(() => {
    const savedMessages = localStorage.getItem('messages');
    
    return savedMessages ? JSON.parse(savedMessages) : [];
  });
  const [input, setInput] = useState('');
  const [language, setLanguage] = useState('en'); // Default language is English
  const [diseases, setDiseases] = useState([]);
  const [lastQueriedDisease, setLastQueriedDisease] = useState(null);
  const navigate = useNavigate();

  const chatBoxRef = useRef(null);

  // Fetch disease data from Django backend
  useEffect(() => {
    const fetchDiseases = async () => {
      try {
        const response = await fetch('http://127.0.0.1:8000/api/diseases/');
        const data = await response.json();
        setDiseases(data);
      } catch (error) {
        console.error('Error fetching disease data:', error);
      }
    };
    fetchDiseases();
  }, []);

  // Save messages to local storage
  useEffect(() => {
    localStorage.setItem('messages', JSON.stringify(messages));
  }, [messages]);

  // Scroll to the bottom of chat messages
  useEffect(() => {
    if (chatBoxRef.current) {
      chatBoxRef.current.scrollTop = chatBoxRef.current.scrollHeight;
    }
  }, [messages]);

  // Translate text using Google Translate API
  const translateText = async (text, targetLang) => {
    if (targetLang === 'en') return text; // Skip translation for English
    try {
      const result = await translate(text, { to: targetLang });
      return result.text;
    } catch (error) {
      console.error('Translation error:', error);
      return text; // Fallback to original text
    }
  };

  // Function to format lists (symptoms, causes, etc.)
  const formatList = (list) => {
    if (Array.isArray(list)) {
      return list.map((item, index) => `${index + 1}. ${item}`).join('\n');
    } else if (typeof list === 'string') {
      return list.split(',').map((item, index) => `${index + 1}. ${item.trim()}`).join('\n');
    }
    return 'No data available';
  };

  // Comprehensive list of greetings in multiple languages
  const globalGreetings = [
    { greeting: 'hello', response: 'Hello! How can I assist you today? 😊' },
    { greeting: 'hi', response: 'Hi! How can I assist you today? 😊' },
    { greeting: 'hey', response: 'Hey! How can I assist you today? 😊' },
    { greeting: 'bonjour', response: 'Bonjour! Comment puis-je vous aider aujourd\'hui? 😊' },
    { greeting: 'hola', response: '¡Hola! ¿Cómo puedo ayudarte hoy? 😊' },
    { greeting: 'hallo', response: 'Hallo! Wie kann ich Ihnen heute helfen? 😊' },
    { greeting: 'ciao', response: 'Ciao! Come posso aiutarti oggi? 😊' },
    { greeting: 'namaste', response: 'नमस्ते! मैं आपकी किस प्रकार सहायता कर सकता हूँ? 😊' },
    { greeting: 'salaam', response: 'सलाम! मैं आपकी किस प्रकार सहायता कर सकता हूँ? 😊' },
    { greeting: 'konichiwa', response: 'こんにちは! 今日、どのようにお手伝いできますか？ 😊' },
    { greeting: 'ni hao', response: '你好! 今天我怎么帮你呢? 😊' },
    { greeting: 'annyeong', response: '안녕하세요! 오늘 어떻게 도와드릴까요? 😊' },
    // Add more greetings as needed
  ];

  // Function to get bot response
  const getBotResponse = async (userInput) => {
    const normalizedInput = userInput.toLowerCase();

    // Handle greetings
    const matchedGreeting = globalGreetings.find((greeting) =>
      normalizedInput.includes(greeting.greeting)
    );

    if (matchedGreeting) {
      const greetingResponse = matchedGreeting.response;
      // Translate the response if necessary based on selected language
      return await translateText(greetingResponse, language);
    }

    // Detect disease-related queries
    const diseaseQueryPattern = /(?:what is|tell me about|enquire about|information on|describe)\s+([\w\s]+)/i;
    const diseaseMatch = diseaseQueryPattern.exec(userInput);

    if (diseaseMatch) {
      const diseaseName = diseaseMatch[1].toLowerCase();
      const matchedDisease = diseases.find((disease) =>
        disease.name.toLowerCase().includes(diseaseName)
      );

      if (matchedDisease) {
        setLastQueriedDisease(matchedDisease);
        let response = `**${matchedDisease.name}:** ${matchedDisease.description}`;
        return await translateText(response, language);
      } else {
        return await translateText("I couldn't find information on that disease. Please try again.", language);
      }
    }

    // Handle disease related queries (list, symptoms, causes, etc.)
    if (normalizedInput.includes('disease') || normalizedInput.includes('list of diseases')) {
      const diseaseList = diseases.map((disease, index) => `${index + 1}. ${disease.name}`).join('\n');
      return await translateText(`Here is a list of diseases:\n${diseaseList}`, language);
    }

    if (normalizedInput.includes('symptom') || normalizedInput.includes('list of symptoms')) {
      if (lastQueriedDisease) {
        const symptomsList = formatList(lastQueriedDisease.symptoms);
        return await translateText(`Symptoms of ${lastQueriedDisease.name}:\n${symptomsList}`, language);
      } else {
        return await translateText('Please specify a disease to get the symptoms.', language);
      }
    }

    if (normalizedInput.includes('cause') || normalizedInput.includes('list of causes')) {
      if (lastQueriedDisease) {
        const causesList = formatList(lastQueriedDisease.causes);
        return await translateText(`Causes of ${lastQueriedDisease.name}:\n${causesList}`, language);
      } else {
        return await translateText('Please specify a disease to get the causes.', language);
      }
    }

    if (normalizedInput.includes('precaution') || normalizedInput.includes('precautions')) {
      if (lastQueriedDisease) {
        const precautionsList = formatList(lastQueriedDisease.precautions);
        return await translateText(`Precautions for ${lastQueriedDisease.name}:\n${precautionsList}`, language);
      } else {
        return await translateText('Please specify a disease to get the precautions.', language);
      }
    }

    if (normalizedInput.includes('medicine') || normalizedInput.includes('list of medicines')) {
      if (lastQueriedDisease) {
        const medicinesList = formatList(lastQueriedDisease.medicines);
        return await translateText(`Medicines for ${lastQueriedDisease.name}:\n${medicinesList}`, language);
      } else {
        return await translateText('Please specify a disease to get the medicines.', language);
      }
    }

    // Fuzzy match disease names
    const matchedDisease = fuzzysort
      .go(normalizedInput, diseases, { key: 'name', threshold: -100 })
      .map((result) => result.obj)[0];

    if (matchedDisease) {
      setLastQueriedDisease(matchedDisease);
      let response = `**${matchedDisease.name}:** ${matchedDisease.description}`;

      // Translate the response
      return await translateText(response, language);
    }

    // Default fallback
    const fallback = "I'm sorry, I couldn't find information on that. Could you try rephrasing?";
    return await translateText(fallback, language);
  };

  // Function to send message
  const sendMessage = async () => {
    if (input.trim()) {
      // Translate user input to selected language
      const translatedInput = await translateText(input, language);

      // Add user message
      setMessages((prevMessages) => [
        ...prevMessages,
        { sender: 'User', text: translatedInput }
      ]);

      // Get bot response
      const botResponse = await getBotResponse(translatedInput);

      // Add bot response
      setMessages((prevMessages) => [
        ...prevMessages,
        { sender: 'Bot', text: botResponse }
      ]);

      setInput('');
    }
  };

  // Function to reset chat
  const resetChat = () => {
    setMessages([]);
    setLastQueriedDisease(null);
    setInput('');
  };

  // Handle language change
  const handleLanguageChange = (lang) => {
    setLanguage(lang);
  };

  // Handle key press (Enter)
  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      sendMessage();
    }
  };

  return (<div className='body'><Navbar/>
  
    <section className="chatbot-container">
    
                    
                <button className="nav-button" onClick={() => navigate(-1)}>
                    <i className="fas fa-arrow-left"></i> Back
                </button>
            
      <div className="language-selector">
        
        <button onClick={() => handleLanguageChange('en')}>English</button>
        <button onClick={() => handleLanguageChange('fr')}>Français</button>
        <button onClick={() => handleLanguageChange('es')}>Español</button>
        <button onClick={() => handleLanguageChange('de')}>Deutsch</button>
        <button onClick={() => handleLanguageChange('hi')}>हिन्दी</button>
        {/* Add more languages as needed */}
      </div>

      <div className="chat-container">
        <div className="chat-box" ref={chatBoxRef}>
          {messages.map((msg, index) => (
            <p key={index} className={`chat-message ${msg.sender.toLowerCase()}`}>
              {msg.text}
            </p>
          ))}
        </div>

        <textarea
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyPress}
          placeholder="Type your question here..."
          rows={2}
          className="chat-input"
        />
        <button onClick={sendMessage} className="send-button">Send</button>
        <button onClick={resetChat} className="reset-button">Reset Chat</button>
      </div>
    </section>
    </div>
  );
}

export default Chatbot;
