// CategoryList.js
import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Navbar from './Navbar';
import './CategoryList.css';
import Footer from './Footer';

function CategoryList() {
    const [diseases, setDiseases] = useState([]);
    const [categories, setCategories] = useState([]);
    const [filteredCategories, setFilteredCategories] = useState([]);
    const [filteredDiseases, setFilteredDiseases] = useState([]); // For diseases under selected category
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState(null); // Track selected category
    const navigate = useNavigate();

    useEffect(() => {
        // Fetch diseases and extract categories
        fetch('http://127.0.0.1:8000/api/diseases/') // Replace with the correct API URL
            .then(response => response.json())
            .then(data => {
                setDiseases(data);

                // Extract unique categories
                const uniqueCategories = [
                    ...new Set(data.map(disease => disease.category)),
                ].filter(category => category); // Filter out null/undefined
                setCategories(uniqueCategories);
                setFilteredCategories(uniqueCategories);
            })
            .catch(error => console.error('Error fetching diseases:', error));
    }, []);

    function handleSearchInput(event) {
        const input = event.target.value;
        setSearchTerm(input);

        // Filter categories based on search input (case-insensitive)
        const suggestions = categories.filter(category =>
            category.toLowerCase().includes(input.toLowerCase())
        );
        setFilteredCategories(suggestions);
    }

    function handleCategorySelect(category) {
        setSelectedCategory(category); // Set the selected category

        // Filter diseases under the selected category
        const diseasesUnderCategory = diseases.filter(
            disease => disease.category === category
        );
        setFilteredDiseases(diseasesUnderCategory);
    }

    const handleShowAllCategories = () => {
        setSelectedCategory('');
        setFilteredDiseases(diseases);
        setFilteredCategories(categories); // Restore all categories
    };

    return (
        <div className="body">
            <Navbar />

            <div className="content-CategoryList">
                <button className="nav-button" onClick={() => navigate(-1)}>
                    <i className="fas fa-arrow-left"></i> Back
                </button>
            
                <div className="searchBar">
                    <input
                        type="text"
                        placeholder="Search categories..."
                        value={searchTerm}
                        onChange={handleSearchInput}
                    />
                    {searchTerm && (
                        <ul className="suggestions">
                            {filteredCategories.map((category, index) => (
                                <li
                                    key={index}
                                    onClick={() => handleCategorySelect(category)}
                                    className="suggestion-item"
                                >
                                    {category}
                                </li>
                            ))}
                        </ul>
                    )}
                    
                </div>
                

                <h1>All Categories</h1>
                {/* Show All Causes Button */}
                {selectedCategory && (
                    <button className="show-all-button" onClick={handleShowAllCategories}>
                        <i className="fas fa-list"></i> Show All Categories
                    </button>
                )}    
                
                {!selectedCategory ? (
                    
                    <ul>
                        {filteredCategories.map((category, index) => (
                            <li key={index}>
                                <button
                                    className="category-button"
                                    onClick={() => handleCategorySelect(category)}
                                >
                                    {category}
                                </button>
                            </li>
                        ))}
                    </ul>
                ) 
                
                : (
                    <div className="disease-list">
                        
                        <h3>Diseases Under "{selectedCategory}"</h3>
                        <ul>
                            {filteredDiseases.length === 0 ? (
                                <p>No diseases found for this cause.</p>
                            ) : (
                                filteredDiseases.map(disease => (
                                    <li key={disease.id}>
                                        <Link to={`/diseases/${disease.id}`}>
                                            <i className="fas fa-disease"></i> {disease.name}
                                        </Link>
                                    </li>
                                ))
                            )}
                        </ul>
                        
                    </div>
                )}
            </div>

            <Footer />
        </div>
    );
}

export default CategoryList;
