import React, { useEffect, useState } from 'react';
import './BloodDonorPage.css';
import axios from 'axios';

const BloodDonorPage = () => {
  const [view, setView] = useState('donors');
  const [donors, setDonors] = useState([]);
  const [camps, setCamps] = useState([]);
  const [filters, setFilters] = useState({ blood_group: '', location: '', sort: 'name' });
  const [donorForm, setDonorForm] = useState({
    name: '',
    age: '',
    gender: '',
    blood_group: '',
    location: '',
    contact: '',
    email: '',
    last_donation: ''
  });
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    if (view === 'donors') fetchDonors();
    else fetchCamps();
  }, [view]);

  const fetchDonors = async () => {
    try {
      const res = await axios.get('http://127.0.0.1:8000/api/blood/donors/');
      let data = res.data;

      const now = new Date();

      // Determine availability
      data = data.map(donor => {
        if (!donor.last_donation) {
          donor.available = true;
        } else {
          const lastDate = new Date(donor.last_donation);
          const monthsDiff = (now - lastDate) / (1000 * 60 * 60 * 24 * 30);
          donor.available = monthsDiff >= 3;
        }
        return donor;
      });

      // Filtering
      if (filters.blood_group) {
        data = data.filter(d => d.blood_group === filters.blood_group);
      }
      if (filters.location) {
        data = data.filter(d => d.location.toLowerCase().includes(filters.location.toLowerCase()));
      }

      // Sorting
      if (filters.sort === 'availability') {
        data.sort((a, b) => (a.available === b.available ? 0 : a.available ? -1 : 1));
      } else if (filters.sort === 'blood_group') {
        const bloodOrder = ['O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'];
        data.sort((a, b) => bloodOrder.indexOf(a.blood_group) - bloodOrder.indexOf(b.blood_group));
      } else {
        data.sort((a, b) => a.name.localeCompare(b.name));
      }

      setDonors(data);
    } catch (err) {
      console.error('Error fetching donors:', err);
    }
  };

  const fetchCamps = async () => {
    try {
      const res = await axios.get('http://127.0.0.1:8000/api/blood/camps/');
      let data = res.data;

      if (filters.location) {
        data = data.filter(c => c.city.toLowerCase().includes(filters.location.toLowerCase()));
      }
      if (filters.sort === 'name') {
        data.sort((a, b) => a.name.localeCompare(b.name));
      }

      setCamps(data);
    } catch (err) {
      console.error('Error fetching camps:', err);
    }
  };

  const handleChange = (e) => {
    setFilters({ ...filters, [e.target.name]: e.target.value });
  };

  const handleFormChange = (e) => {
    setDonorForm({ ...donorForm, [e.target.name]: e.target.value });
  };

  const handleSearch = () => {
    view === 'donors' ? fetchDonors() : fetchCamps();
  };

  const handleRegister = async () => {
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/blood/donors/', donorForm);
      alert('Donor Registered Successfully!');
      fetchDonors();
      setShowForm(false);
    } catch (err) {
      console.error('Error registering donor:', err);
      alert('Failed to register donor!');
    }
  };

  return (
    <div className="donor-page">
      <div className="sidebar">
        <h2>Blood Portal</h2>

        <div className="tab-buttons">
          <button className={view === 'donors' ? 'active' : ''} onClick={() => setView('donors')}>Find Donors</button>
          <button className={view === 'camps' ? 'active' : ''} onClick={() => setView('camps')}>Blood Camps</button>
        </div>

        {view === 'donors' && (
          <>
            <select name="blood_group" value={filters.blood_group} onChange={handleChange}>
              <option value="">All Blood Groups</option>
              <option value="O-">O-</option>
              <option value="O+">O+</option>
              <option value="A-">A-</option>
              <option value="A+">A+</option>
              <option value="B-">B-</option>
              <option value="B+">B+</option>
              <option value="AB-">AB-</option>
              <option value="AB+">AB+</option>
            </select>

            <input
              type="text"
              name="location"
              value={filters.location}
              onChange={handleChange}
              placeholder="Location/City"
            />

            <select name="sort" value={filters.sort} onChange={handleChange}>
              <option value="name">Sort by: Name</option>
              <option value="availability">Sort by: Availability</option>
            </select>

            <button className="search-btn" onClick={handleSearch}>Search</button>

            <div className="info-box">
              <p>• Donors must wait 3 months between donations</p>
              <p>• Age must be between 18–65 years</p>
              <p>• Weight ≥ 50kg</p>
              <p>• Hemoglobin level should be adequate</p>
            </div>

            <button className="register-btn" onClick={() => setShowForm(true)}>Register as Donor</button>
          </>
        )}
      </div>

      <div className="donor-list">
        {view === 'donors' ? (
          <>
            <h2>Available Blood Donors</h2>
            {donors.map(donor => (
              <div className="donor-card" key={donor.id}>
                <div className="blood-group-badge">{donor.blood_group}</div>
                <h3>{donor.name}</h3>
                <div className='age_loc'>
                  <p>{donor.age} years, {donor.gender}</p>
                  <p>{donor.location}</p>
                </div>
                <p className="highlight">Contact: {donor.contact}</p>
                <p className="highlight">Email: {donor.email || 'N/A'}</p>
                <p className="highlight">Last Donation: {donor.last_donation || 'N/A'}</p>
                <p className={donor.available ? 'available' : 'not-available'}>
                  {donor.available ? 'Available for donation' : 'Not Available'}
                </p>
              </div>
            ))}
          </>
        ) : (
          <>
            <h2>Upcoming Blood Camps</h2>
            {camps.map(camp => (
              <div className="donor-card" key={camp.id}>
                <h3>{camp.name}</h3>
                <p>{camp.city}, {camp.state}</p>
                <p className="highlight">Venue: {camp.venue}</p>
                <p className="highlight">Date: {camp.date}</p>
                <p>Organized by: {camp.organizer}</p>
              </div>
            ))}
          </>
        )}
      </div>

      {showForm && (
        <div className="register-form">
          <h3>Register as Donor</h3>
          <input type="text" name="name" placeholder="Name" value={donorForm.name} onChange={handleFormChange} />
          <input type="number" name="age" placeholder="Age" value={donorForm.age} onChange={handleFormChange} />
          <select name="gender" value={donorForm.gender} onChange={handleFormChange}>
            <option value="">Select Gender</option>
            <option value="Male">Male</option>
            <option value="Female">Female</option>
            <option value="Other">Other</option>
          </select>
          <select name="blood_group" value={donorForm.blood_group} onChange={handleFormChange}>
            <option value="">Select Blood Group</option>
            <option value="O-">O-</option>
            <option value="O+">O+</option>
            <option value="A-">A-</option>
            <option value="A+">A+</option>
            <option value="B-">B-</option>
            <option value="B+">B+</option>
            <option value="AB-">AB-</option>
            <option value="AB+">AB+</option>
          </select>
          <input type="text" name="location" placeholder="Location" value={donorForm.location} onChange={handleFormChange} />
          <input type="text" name="contact" placeholder="Contact" value={donorForm.contact} onChange={handleFormChange} />
          <input type="email" name="email" placeholder="Email (Optional)" value={donorForm.email} onChange={handleFormChange} />
          <input type="date" name="last_donation" placeholder="Last Donation Date" value={donorForm.last_donation} onChange={handleFormChange} />
          <button onClick={handleRegister}>Register</button>
          <button onClick={() => setShowForm(false)}>Cancel</button>
        </div>
      )}
    </div>
  );
};

export default BloodDonorPage;
