import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Navbar.css';

function Navbar() {
    const [menuActive, setMenuActive] = useState(false);

    const toggleMenu = () => {
        setMenuActive(!menuActive);
    };

    return (
        <nav className="navbar">
            {/* Logo or Brand */}
            <Link to="/" className="logo">CuraAMS</Link>

            {/* Hamburger Menu */}
            <div className={`hamburger ${menuActive ? 'active' : ''}`} onClick={toggleMenu}>
                <span></span>
                <span></span>
                <span></span>
            </div>

            {/* Navigation Links */}
            <div className={`menu ${menuActive ? 'active' : ''}`}>
                <Link to="/" onClick={() => setMenuActive(false)}>Home</Link>
                <Link to="/categories" onClick={() => setMenuActive(false)}>Categories</Link>
                <Link to="/symptoms" onClick={() => setMenuActive(false)}>Symptoms</Link>
                <Link to="/causes" onClick={() => setMenuActive(false)}>Causes</Link>
                <Link to="/diseases" onClick={() => setMenuActive(false)}>All Diseases</Link>
                <Link to="/chatbot" onClick={() => setMenuActive(false)}>Chatbot</Link>
            </div>
        </nav>
    );
}

export default Navbar;
