import React, { useState } from 'react';

function AdminPanel() {
    const [file, setFile] = useState(null);

    function handleFileChange(event) {
        setFile(event.target.files[0]);
    }

    function handleUpload() {
        const formData = new FormData();
        formData.append('file', file);

        fetch('/api/upload-js/', {
            method: 'POST',
            body: formData,
        })
            .then(response => response.js())
            .then(data => alert('Data uploaded successfully!'))
            .catch(error => alert('Error uploading data.'));
    }

    return (
        <div>
            <h2>Admin Panel</h2>
            <input type="file" onChange={handleFileChange} accept=".js" />
            <button onClick={handleUpload}>Upload JSON</button>
        </div>
    );
}

export default AdminPanel;
