//DiseaseList.js
import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Navbar from './Navbar';
import './DiseaseList.css';
import Footer from './Footer';

function DiseaseList() {
    const [diseases, setDiseases] = useState([]);
    const [filteredDiseases, setFilteredDiseases] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const navigate = useNavigate();

    useEffect(() => {
        fetch('http://127.0.0.1:8000/api/diseases/') // Update with your correct API URL
            .then(response => response.json())
            .then(data => {
                setDiseases(data);
                setFilteredDiseases(data);
            })
            .catch(error => console.error('Error fetching diseases:', error));
    }, []);

    function handleSearchInput(event) {
        const input = event.target.value;
        setSearchTerm(input);

        // Filter diseases based on search input (case-insensitive)
        const suggestions = diseases.filter(disease =>
            disease.name.toLowerCase().includes(input.toLowerCase())
        );
        setFilteredDiseases(suggestions);
    }

    function handleSelectDisease(disease) {
        // Navigate to the disease detail page
        navigate(`/diseases/${disease.id}`);
    }

    return (
        <div className="body">
            <Navbar />
            
            <div className="content-DiseaseList">
                <button className="nav-button" onClick={() => navigate(-1)}>
                    <i className="fas fa-arrow-left"></i> Back
                </button>
                <div className="searchBar">
                    <input
                        type="text"
                        placeholder="Search diseases..."
                        value={searchTerm}
                        onChange={handleSearchInput}
                    />
                    {searchTerm && (
                        <ul className="suggestions">
                            {filteredDiseases.map(disease => (
                                <li
                                    key={disease.id}
                                    onClick={() => handleSelectDisease(disease)}
                                    className="suggestion-item"
                                >
                                    {disease.name}
                                </li>
                            ))}
                        </ul>
                    )}
                </div>
                <h1>All Diseases</h1>
                <ul>
                    {filteredDiseases.map(disease => (
                        <li key={disease.id}>
                            <Link to={`/diseases/${disease.id}`}>{disease.name}</Link>
                        </li>
                    ))}
                </ul>
            </div>
            <Footer/>
        </div>
    );
}

export default DiseaseList;
