//CauseList.js
import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Navbar from './Navbar';
import "./CauseList.css";
import Footer from './Footer';

function CauseList() {
    const [diseases, setDiseases] = useState([]);
    const [filteredDiseases, setFilteredDiseases] = useState([]);
    const [causes, setCauses] = useState([]);
    const [filteredCauses, setFilteredCauses] = useState([]);
    const [selectedCause, setSelectedCause] = useState('');
    const [searchQuery, setSearchQuery] = useState('');
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();

    useEffect(() => {
        // Fetch diseases and process causes
        fetch('http://127.0.0.1:8000/api/diseases/')
            .then(response => response.json())
            .then(data => {
                setDiseases(data);
                setFilteredDiseases(data);

                // Extract unique, individual causes
                const allCauses = data.flatMap(disease =>
                    disease.causes.split(',').map(cause => cause.trim())
                );
                const uniqueCauses = [...new Set(allCauses)];
                setCauses(uniqueCauses);
                setFilteredCauses(uniqueCauses); // Initially show all causes
            })
            .catch(error => console.error('Error fetching diseases:', error))
            .finally(() => setLoading(false));
    }, []);

    const handleCauseClick = (cause) => {
        setSelectedCause(cause);
        const filtered = diseases.filter(disease =>
            disease.causes.split(',').map(c => c.trim()).includes(cause)
        );
        setFilteredDiseases(filtered);
        setSearchQuery(''); // Clear search bar
        setFilteredCauses([]); // Hide suggestions
    };

    const handleSearchChange = (event) => {
        const query = event.target.value.toLowerCase();
        setSearchQuery(query);

        if (query === '') {
            setFilteredCauses(causes); // Show all causes if query is empty
        } else {
            const filtered = causes.filter(cause =>
                cause.toLowerCase().includes(query)
            );
            setFilteredCauses(filtered); // Show matching causes
        }
    };

    const handleShowAllCauses = () => {
        setSelectedCause('');
        setFilteredDiseases(diseases);
        setSearchQuery('');
        setFilteredCauses(causes); // Restore all causes
    };

    if (loading) {
        return (
            <div className="spinner-container">
                <div className="spinner"></div>
                <p>Loading causes and diseases...</p>
            </div>
        );
    }

    return (
        <div className="body">
            <Navbar />
            <div className="content-CauseList">
                <button className="nav-button" onClick={() => navigate(-1)}>
                    <i className="fas fa-arrow-left"></i> Back
                </button>
                <h1>Causes</h1>

                {/* Search Bar */}
                {!selectedCause && (
                    <div className="search-container">
                        <input
                            type="text"
                            className="search-bar"
                            placeholder="Search Causes..."
                            value={searchQuery}
                            onChange={handleSearchChange}
                        />
                        <i className="fas fa-search search-icon"></i>
                    </div>
                )}

                {/* Show All Causes Button */}
                {selectedCause && (
                    <button className="show-all-button" onClick={handleShowAllCauses}>
                        <i className="fas fa-list"></i> Show All Causes
                    </button>
                )}

                {/* Cause Buttons */}
                {!selectedCause && !searchQuery && (
                    <ul className="cause-list">
                        {causes.map((cause, index) => (
                            <li key={index} className="cause-item">
                                <button onClick={() => handleCauseClick(cause)}>
                                    <i className="fas fa-virus"></i> {cause}
                                </button>
                            </li>
                        ))}
                    </ul>
                )}

                {/* Display Filtered Causes */}
                {searchQuery && !selectedCause && (
                    <ul className="cause-list">
                        {filteredCauses.length === 0 ? (
                            <p>No matching causes found.</p>
                        ) : (
                            filteredCauses.map((cause, index) => (
                                <li key={index} className="cause-item">
                                    <button onClick={() => handleCauseClick(cause)}>
                                        <i className="fas fa-virus"></i> {cause}
                                    </button>
                                </li>
                            ))
                        )}
                    </ul>
                )}

                {/* Disease List */}
                {selectedCause && (
                    <div className="disease-list">
                        <h3>Diseases Under "{selectedCause}"</h3>
                        <ul>
                            {filteredDiseases.length === 0 ? (
                                <p>No diseases found for this cause.</p>
                            ) : (
                                filteredDiseases.map(disease => (
                                    <li key={disease.id}>
                                        <Link to={`/diseases/${disease.id}`}>
                                            <i className="fas fa-disease"></i> {disease.name}
                                        </Link>
                                    </li>
                                ))
                            )}
                        </ul>
                    </div>
                )}
            </div>
            <Footer/>
        </div>
    );
}

export default CauseList;
