//SymptomList.js
import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Navbar from './Navbar';
import "./SymptomList.css";
import Footer from './Footer';

function SymptomList() {
    const [diseases, setDiseases] = useState([]);
    const [filteredDiseases, setFilteredDiseases] = useState([]);
    const [symptoms, setSymptoms] = useState([]);
    const [filteredSymptoms, setFilteredSymptoms] = useState([]);
    const [selectedSymptom, setSelectedSymptom] = useState('');
    const [searchQuery, setSearchQuery] = useState('');
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();

    useEffect(() => {
        // Fetch diseases and process symptoms
        fetch('http://127.0.0.1:8000/api/diseases/')
            .then(response => response.json())
            .then(data => {
                setDiseases(data);
                setFilteredDiseases(data);

                // Extract unique, individual symptoms
                const allSymptoms = data.flatMap(disease =>
                    disease.symptoms.split(',').map(symptom => symptom.trim())
                );
                const uniqueSymptoms = [...new Set(allSymptoms)];
                setSymptoms(uniqueSymptoms);
                setFilteredSymptoms(uniqueSymptoms); // Initially show all symptoms
            })
            .catch(error => console.error('Error fetching diseases:', error))
            .finally(() => setLoading(false));
    }, []);

    const handleSymptomClick = (symptom) => {
        setSelectedSymptom(symptom);
        const filtered = diseases.filter(disease =>
            disease.symptoms.split(',').map(c => c.trim()).includes(symptom)
        );
        setFilteredDiseases(filtered);
        setSearchQuery(''); // Clear search bar
        setFilteredSymptoms([]); // Hide suggestions
    };

    const handleSearchChange = (event) => {
        const query = event.target.value.toLowerCase();
        setSearchQuery(query);

        if (query === '') {
            setFilteredSymptoms(symptoms); // Show all symptoms if query is empty
        } else {
            const filtered = symptoms.filter(symptom =>
                symptom.toLowerCase().includes(query)
            );
            setFilteredSymptoms(filtered); // Show matching symptoms
        }
    };

    const handleShowAllSymptoms = () => {
        setSelectedSymptom('');
        setFilteredDiseases(diseases);
        setSearchQuery('');
        setFilteredSymptoms(symptoms); // Restore all symptoms
    };

    if (loading) {
        return (
            <div className="spinner-container">
                <div className="spinner"></div>
                <p>Loading symptoms and diseases...</p>
            </div>
        );
    }

    return (
        <div className="body">
            <Navbar />
            <div className="content-SymptomList">
                 <button className="nav-button" onClick={() => navigate(-1)}>
                    <i className="fas fa-arrow-left"></i> Back
                </button>

                <h1>Symptoms</h1>

                {/* Search Bar */}
                {!selectedSymptom && (
                    <div className="search-container">
                        <input
                            type="text"
                            className="search-bar"
                            placeholder="Search Symptoms..."
                            value={searchQuery}
                            onChange={handleSearchChange}
                        />
                        <i className="fas fa-search search-icon"></i>
                    </div>
                )}

                {/* Show All Symptoms Button */}
                {selectedSymptom && (
                    <button className="show-all-button" onClick={handleShowAllSymptoms}>
                        <i className="fas fa-list"></i> Show All Symptoms
                    </button>
                )}

                {/* Symptom Buttons */}
                {!selectedSymptom && !searchQuery && (
                    <ul className="symptom-list">
                        {symptoms.map((symptom, index) => (
                            <li key={index} className="symptom-item">
                                <button onClick={() => handleSymptomClick(symptom)}>
                                    <i className="fas fa-virus"></i> {symptom}
                                </button>
                            </li>
                        ))}
                    </ul>
                )}

                {/* Display Filtered Symptoms */}
                {searchQuery && !selectedSymptom && (
                    <ul className="symptom-list">
                        {filteredSymptoms.length === 0 ? (
                            <p>No matching symptoms found.</p>
                        ) : (
                            filteredSymptoms.map((symptom, index) => (
                                <li key={index} className="symptom-item">
                                    <button onClick={() => handleSymptomClick(symptom)}>
                                        <i className="fas fa-virus"></i> {symptom}
                                    </button>
                                </li>
                            ))
                        )}
                    </ul>
                )}

                {/* Disease List */}
                {selectedSymptom && (
                    <div className="disease-list">
                        <h3>Diseases Under "{selectedSymptom}"</h3>
                        <ul>
                            {filteredDiseases.length === 0 ? (
                                <p>No diseases found for this symptom.</p>
                            ) : (
                                filteredDiseases.map(disease => (
                                    <li key={disease.id}>
                                        <Link to={`/diseases/${disease.id}`}>
                                            <i className="fas fa-disease"></i> {disease.name}
                                        </Link>
                                    </li>
                                ))
                            )}
                        </ul>
                    </div>
                )}
            </div>
            <Footer/>
        </div>
    );
}

export default SymptomList;
