import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './GovernmentSchemes.css';

const GovernmentSchemes = () => {
  const [schemes, setSchemes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState('');
  const [expandedScheme, setExpandedScheme] = useState(null);

  useEffect(() => {
    const fetchSchemes = async () => {
      try {
        const res = await axios.get('http://127.0.0.1:8000/api/schemes/');
        setSchemes(res.data);
        setLoading(false);
      } catch (err) {
        setError('Failed to load schemes');
        setLoading(false);
      }
    };

    fetchSchemes();
  }, []);

  const filteredSchemes = schemes.filter((scheme) =>
    scheme.name.toLowerCase().includes(search.toLowerCase())
  );

  const handleLearnMoreClick = (id) => {
    setExpandedScheme(id === expandedScheme ? null : id); // Toggle the expanded view
  };

  return (
    <div className="schemes-page">
      <div className="schemes-header">
        <h1>Government Medical Schemes</h1>
        <input
          type="text"
          placeholder="Search schemes..."
          className="scheme-search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {loading ? (
        <div className="loading-container">
          <div className="spinner"></div>
          <p>Loading...</p>
        </div>
      ) : error ? (
        <p className="error-message">{error}</p>
      ) : filteredSchemes.length === 0 ? (
        <p className="error-message">No schemes found.</p>
      ) : (
        <div className="scheme-list">
          {filteredSchemes.map((scheme) => (
            <div className="scheme-item" key={scheme.id}>
              <h2>{scheme.name}</h2>
              <p>{scheme.description.slice(0, 150)}...</p>
              <button
                className="learn-more-btn"
                onClick={() => handleLearnMoreClick(scheme.id)}
              >
                Learn More
              </button>

              {expandedScheme === scheme.id && (
                <div className="expanded-content">
                  <p><strong>Full Description:</strong> {scheme.description}</p>
                  <p><strong>Eligibility:</strong> {scheme.eligibility}</p>
                  {scheme.link && (
                    <p>
                      <strong>Apply Link:</strong>
                      <a href={scheme.link} target="_blank" rel="noopener noreferrer">
                        Apply Here
                      </a>
                    </p>
                  )}
                  {scheme.photo && (
                    <div className="scheme-photo">
                      <img src={scheme.photo} alt={scheme.name} />
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default GovernmentSchemes;
