import React, { useState } from 'react';
import './BodyFatCalculator.css';

const BodyFatCalculator = () => {
  const [height, setHeight] = useState('');
  const [waist, setWaist] = useState('');
  const [neck, setNeck] = useState('');
  const [hip, setHip] = useState('');
  const [gender, setGender] = useState('');
  const [unit, setUnit] = useState('cm');  // Default unit: cm
  const [bodyFat, setBodyFat] = useState(null);
  const [message, setMessage] = useState('');
  const [fatRangeMessage, setFatRangeMessage] = useState('');

  const calculateBodyFat = () => {
    if (height && waist && neck && gender) {
      let fatPercentage = 0;
      const heightInCm = unit === 'inches' ? height * 2.54 : height;
      const waistInCm = unit === 'inches' ? waist * 2.54 : waist;
      const neckInCm = unit === 'inches' ? neck * 2.54 : neck;
      const hipInCm = unit === 'inches' ? hip * 2.54 : hip;

      if (gender === 'male') {
        fatPercentage = (
          (86.010 * Math.log10(waistInCm - neckInCm)) - 
          (70.041 * Math.log10(heightInCm)) + 
          36.76
        ).toFixed(2);
      } else if (gender === 'female' && hip) {
        fatPercentage = (
          (163.205 * Math.log10(waistInCm + hipInCm - neckInCm)) - 
          (97.684 * Math.log10(heightInCm)) - 
          78.387
        ).toFixed(2);
      } else {
        setMessage('Please enter all required fields.');
        setBodyFat(null);
        setFatRangeMessage('');
        return;
      }

      if (isNaN(fatPercentage) || fatPercentage <= 0) {
        setMessage('Please enter valid inputs for all fields.');
        setBodyFat(null);
        setFatRangeMessage('');
        return;
      }

      setBodyFat(fatPercentage);
      setMessage(`Your Body Fat Percentage is ${fatPercentage}%`);

      if (fatPercentage < 6) {
        setFatRangeMessage('Essential Fat: Too low, not recommended for most people.');
      } else if (fatPercentage >= 6 && fatPercentage <= 13) {
        setFatRangeMessage('Athletes: Healthy range for athletes.');
      } else if (fatPercentage > 13 && fatPercentage <= 17) {
        setFatRangeMessage('Fitness: Healthy for fitness enthusiasts.');
      } else if (fatPercentage > 17 && fatPercentage <= 24) {
        setFatRangeMessage('Average: Healthy for the average population.');
      } else {
        setFatRangeMessage('Obese: High body fat percentage, may indicate obesity.');
      }
    } else {
      setMessage('Please fill out all fields.');
      setBodyFat(null);
      setFatRangeMessage('');
    }
  };

  return (
    <div className="body-fat-calculator-wrapper">
      <div className="body-fat-main-container">
        <div className="body-fat-calculator">
          <h2>Body Fat Percentage Calculator</h2> 
          <div className="input-fields">
            <select
              value={gender}
              onChange={(e) => setGender(e.target.value)}
              className="gender-select"
            >
              <option value="">Select Gender</option>
              <option value="male">Male</option>
              <option value="female">Female</option>
            </select>

            <input
              type="number"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
              placeholder={unit === 'inches' ? "Height (inches)" : "Height (cm)"}
              className="input-field"
            />

            <input
              type="number"
              value={waist}
              onChange={(e) => setWaist(e.target.value)}
              placeholder={unit === 'inches' ? "Waist (inches)" : "Waist (cm)"}
              className="input-field"
            />

            <input
              type="number"
              value={neck}
              onChange={(e) => setNeck(e.target.value)}
              placeholder={unit === 'inches' ? "Neck (inches)" : "Neck (cm)"}
              className="input-field"
            />

            {gender === 'female' && (
              <input
                type="number"
                value={hip}
                onChange={(e) => setHip(e.target.value)}
                placeholder={unit === 'inches' ? "Hip (inches)" : "Hip (cm)"}
                className="input-field"
              />
            )}

            <div className="unit-selection">
              <label>Units: </label>
              <select
                value={unit}
                onChange={(e) => setUnit(e.target.value)}
                className="unit-select"
              >
                <option value="cm">Centimeters (cm)</option>
                <option value="inches">Inches (in)</option>
              </select>
            </div>
          </div>

          <div className="fat_result">
            {bodyFat && <h3>Your Body Fat Percentage: {bodyFat}%</h3>}
            <p>{message}</p>
            <p>{fatRangeMessage}</p>
          </div>
            
          <button onClick={calculateBodyFat} className="calculate-btn">
            Calculate
          </button>
          
        </div>

        <div className="body-fat-content">
          <div className="body-fat-formula">
            <h3>Body Fat Percentage Calculation Formula</h3>
            <p>For Men: <br /> Body Fat Percentage = 86.010 × log10(waist - neck) - 70.041 × log10(height) + 36.76</p>
            <p>For Women: <br /> Body Fat Percentage = 163.205 × log10(waist + hip - neck) - 97.684 × log10(height) - 78.387</p>
          </div>

          <div className="body-fat-ranges">
            <h3>Body Fat Percentage Ranges</h3>
            <ul>
              <li><strong>Essential Fat:</strong> Less than 6% (too low, not recommended for most people)</li>
              <li><strong>Athletes:</strong> 6% - 13% (healthy range for athletes)</li>
              <li><strong>Fitness:</strong> 14% - 17% (healthy for fitness enthusiasts)</li>
              <li><strong>Average:</strong> 18% - 24% (healthy for the average population)</li>
              <li><strong>Obese:</strong> 25% or more (high body fat percentage, may indicate obesity)</li>
            </ul>
          </div>
        </div>
       
      </div>
    </div>
  );
};

export default BodyFatCalculator;
